using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Security.Cryptography;

namespace Arc.Crypto;

/// <summary>
/// A thread-safe random number pool that buffers output from a supplied generator.<br/>
/// All calls the vault makes to the generator are serialized, including requests that bypass the buffer.<br/>
/// Do not use the wrapped generator outside the vault concurrently.
/// </summary>
/// <remarks>
/// Generated bytes stay in the vault's internal buffer until it is refilled, including bytes that have already been returned.<br/>
/// Callers that need key material without such a heap copy should fill their own buffer directly with
/// <see cref="RandomNumberGenerator.Fill(Span{byte})"/> or <see cref="CryptoRandom.NextBytes(Span{byte})"/>.
/// </remarks>
public class RandomVault : RandomUInt64Base
{
    private const int DefaultBufferSize = 4096;
    private const int DefaultSkipVaultThreshold = 256;

    /// <summary>
    /// Gets the default cryptographically secure pseudo-random number pool (<see cref="AegisRandom"/>).<br/>
    /// Same instance as <see cref="Aegis"/>.
    /// </summary>
    public static RandomVault Default => Aegis;

    /// <summary>
    /// Gets the cryptographically secure pseudo-random number pool (<see cref="AegisRandom"/>).
    /// </summary>
    public static RandomVault Aegis => AegisHolder.Instance;

    /// <summary>
    /// Gets a fast, non-cryptographic pseudo-random number pool (<see cref="Xoshiro256StarStar"/>).<br/>
    /// Do not use it for keys, nonces or other secrets.
    /// </summary>
    public static RandomVault Xoshiro => XoshiroHolder.Instance;

    /// <summary>
    /// Gets the cryptographically secure pseudo-random number pool (<see cref="RandomNumberGenerator.Fill(Span{byte})"/>).
    /// </summary>
    public static RandomVault SystemRng => SystemRngHolder.Instance;

    /// <summary>
    /// Gets the cryptographically secure pseudo-random number pool (Libsodium: <see cref="CryptoRandom.NextBytes(Span{byte})"/>).
    /// </summary>
    public static RandomVault Libsodium => LibsodiumHolder.Instance;

    /// <summary>
    /// Initializes a new instance of the <see cref="RandomVault"/> class.
    /// </summary>
    /// <param name="nextBytes">A delegate that fills the entire span with random bytes. The vault serializes its calls.</param>
    /// <param name="skipVaultThreshold">Requests that still need more than this many bytes after the buffered bytes are used are filled directly by <paramref name="nextBytes"/>.<br/>
    /// Values above <see cref="BufferSize"/> are capped. The default is 256.</param>
    /// <exception cref="ArgumentNullException"><paramref name="nextBytes"/> is <see langword="null"/>.</exception>
    /// <exception cref="ArgumentOutOfRangeException"><paramref name="skipVaultThreshold"/> is negative.</exception>
    public RandomVault(Action<Span<byte>> nextBytes, int skipVaultThreshold = DefaultSkipVaultThreshold)
    {
        ArgumentNullException.ThrowIfNull(nextBytes);
        ArgumentOutOfRangeException.ThrowIfNegative(skipVaultThreshold);
        this.nextBytesFunc = nextBytes;
        this.BufferSize = DefaultBufferSize;
        this.buffer = new byte[this.BufferSize];
        this.skipVaultThreshold = Math.Min(skipVaultThreshold, this.BufferSize);
    }

    /// <summary>
    /// Generates the next random 64-bit unsigned integer.
    /// </summary>
    /// <returns>A random 64-bit unsigned integer.</returns>
    public override ulong NextUInt64()
    {
        using (this.lockObject.EnterScope())
        {
            if (this.remaining >= sizeof(ulong))
            {
                var value = MemoryMarshal.Read<ulong>(this.buffer.AsSpan(this.position));
                this.remaining -= sizeof(ulong);
                return value;
            }
            else
            {
                Span<byte> tmp = stackalloc byte[sizeof(ulong)];
                var a = this.remaining;
                var b = sizeof(ulong) - this.remaining;
                this.buffer.AsSpan(this.position, a).CopyTo(tmp);

                this.PrepareBuffer();
                this.buffer.AsSpan(this.position, b).CopyTo(tmp.Slice(a));
                this.remaining -= b;

                return MemoryMarshal.Read<ulong>(tmp);
            }
        }
    }

    /// <summary>
    /// Fills the elements of a specified span of bytes with random numbers.
    /// </summary>
    /// <param name="destination">The span to fill with random numbers.</param>
    public override void NextBytes(Span<byte> destination)
    {
        if (destination.IsEmpty)
        {
            return;
        }

        using (this.lockObject.EnterScope())
        {
            // First, attempt to consume the prepared buffer.
            var n = Math.Min(destination.Length, this.remaining);
            if (n > 0)
            {
                this.buffer.AsSpan(this.position, n).CopyTo(destination);
                this.remaining -= n;
                destination = destination.Slice(n);
            }

            if (destination.Length == 0)
            {
                return;
            }

            if (destination.Length > this.skipVaultThreshold)
            {// If it is above the threshold, use the underlying function.
                this.nextBytesFunc(destination);
                // this.PrepareBuffer();
            }
            else
            {// For other cases, prepare the buffer first and then copy (it is ensured that destination.Length is less than or equal to skipVaultThreshold/BufferSize).
                this.PrepareBuffer();
                this.buffer.AsSpan(0, destination.Length).CopyTo(destination);
                this.remaining -= destination.Length;
            }
        }
    }

    /// <summary>
    /// Prepares the buffer by filling it with random bytes.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void PrepareBuffer()
    {
        this.nextBytesFunc(this.buffer);
        this.remaining = this.BufferSize;
    }

    /// <summary>
    /// Gets the size, in bytes, of the internal buffer.
    /// </summary>
    public int BufferSize { get; }

    private readonly Action<Span<byte>> nextBytesFunc;
    private readonly int skipVaultThreshold;
    private readonly Lock lockObject = new();
    private readonly byte[] buffer;
    private int remaining;

    private int position => this.BufferSize - this.remaining;

    // Each shared vault is created on first use; the type initializer of its holder runs exactly once.
    private static class AegisHolder
    {
        internal static readonly RandomVault Instance = new(new AegisRandom().NextBytes, 16);
    }

    private static class XoshiroHolder
    {
        internal static readonly RandomVault Instance = new(new Xoshiro256StarStar().NextBytes, 16);
    }

    private static class SystemRngHolder
    {
        internal static readonly RandomVault Instance = new(RandomNumberGenerator.Fill);
    }

    private static class LibsodiumHolder
    {
        internal static readonly RandomVault Instance = new(CryptoRandom.NextBytes);
    }
}
